import json,numpy as np
from PIL import Image
b='/app/runs/current_retry_lift';im=np.array(Image.open(b+'/last/wrist_cam.jpg'));d=np.load(b+'/last_depth_wrist_cam.npy');m=json.load(open(b+'/meta.json'));E=np.array(m['cameras']['wrist_cam']['extrinsic_cv']);K=np.array(m['cameras']['wrist_cam']['intrinsic_cv']);R=E[:,:3];t=E[:,3]
P=np.array(m['proprio']['now'][8:11]);print('tcp',P)
for c in [(0,300,350,650),(0,300,450,650),(50,300,350,650),(0,250,500,650)]:
 x0,y0,x1,y1=c;gray=im[y0:y1,x0:x1].mean(2);yy,xx=np.where((gray<50)&(d[y0:y1,x0:x1]>.01)&(d[y0:y1,x0:x1]<.8));xx+=x0;yy+=y0;ps=[]
 for x,y in zip(xx,yy):ps.append(R.T@(np.linalg.inv(K)@np.array([x,y,1.])*float(d[y,x])-t))
 ps=np.array(ps)
 if len(ps):print(c,len(ps),'pix', (xx.min(),yy.min(),xx.max(),yy.max()),'world',np.round(np.min(ps,0),3),np.round(np.max(ps,0),3),'median',np.round(np.median(ps,0),3))
for q in [[.27,.30,.02],[.34,.28,.02],[.27,.30,.214]]:
 v=R@np.array(q)+t;uv=K@v;print('project',q, np.round(uv[:2]/uv[2],1),v[2])
PY

